import React, { useState, useMemo } from "react";

// ─── Types ───────────────────────────────────────────────────────────────────

type UserStatus = "active" | "pending" | "suspended" | "dormant";
type UserRole = "admin" | "driver" | "user";

interface User {
  id: number;
  name: string;
  email: string;
  phone: string;
  role: UserRole;
  status: UserStatus;
  joined: string;
  lastActive: string;
  lastActiveNote?: string;
  avatarUrl?: string;
}

// ─── Mock Data ───────────────────────────────────────────────────────────────

const MOCK_USERS: User[] = [
  { id: 1,  name: "Anne Wanjiku",        email: "wanjikugichuhi9@gmail.com",  phone: "0711645655",      role: "user",   status: "active",    joined: "5/22/2026", lastActive: "5/22/2026", lastActiveNote: "Registered" },
  { id: 2,  name: "Huba Adventures",     email: "hubaadventures@gmail.com",   phone: "No phone",        role: "user",   status: "active",    joined: "5/22/2026", lastActive: "5/22/2026" },
  { id: 3,  name: "Nafit Explorers Africa", email: "nafitexplorers@gmail.com", phone: "+254 720 000 001", role: "driver", status: "active",   joined: "5/22/2026", lastActive: "5/22/2026" },
  { id: 4,  name: "James Kariuki",       email: "j.kariuki@weera.co",         phone: "0733456789",      role: "driver", status: "dormant",   joined: "3/8/2024",  lastActive: "4/1/2024" },
  { id: 5,  name: "Sofia Adeyemi",       email: "sofia.a@weera.co",           phone: "0803567890",      role: "user",   status: "suspended", joined: "3/15/2024", lastActive: "3/20/2024" },
  { id: 6,  name: "Kai Nguyen",          email: "kai.n@weera.co",             phone: "091 678 9012",    role: "driver", status: "active",    joined: "4/2/2024",  lastActive: "5/20/2026" },
  { id: 7,  name: "Zara Ahmed",          email: "zara.ahmed@weera.co",        phone: "0321 789 0123",   role: "user",   status: "active",    joined: "4/18/2024", lastActive: "5/21/2026" },
  { id: 8,  name: "Mateo Ruiz",          email: "mateo.r@weera.co",           phone: "55 890 1234",     role: "admin",  status: "active",    joined: "5/1/2024",  lastActive: "5/22/2026" },
  { id: 9,  name: "Priya Sharma",        email: "priya.s@weera.co",           phone: "98765 43210",     role: "user",   status: "pending",   joined: "5/20/2024", lastActive: "5/1/2024" },
  { id: 10, name: "Noah Kimani",         email: "n.kimani@weera.co",          phone: "0720 901 234",    role: "driver", status: "active",    joined: "6/5/2024",  lastActive: "5/22/2026" },
  { id: 11, name: "Isla Chen",           email: "isla.c@weera.co",            phone: "138 0123 4567",   role: "user",   status: "dormant",   joined: "6/22/2024", lastActive: "2/1/2024" },
  { id: 12, name: "Yuki Tanaka",         email: "yuki.t@weera.co",            phone: "90 1234 5678",    role: "user",   status: "active",    joined: "7/15/2024", lastActive: "5/15/2026" },
  { id: 13, name: "Lena Müller",         email: "lena.m@weera.co",            phone: "+49 172 345 6789", role: "user",  status: "active",    joined: "2/3/2024",  lastActive: "5/22/2026" },
  { id: 14, name: "Omar Diallo",         email: "o.diallo@weera.co",          phone: "+221 77 012 3456", role: "driver", status: "active",   joined: "7/3/2024",  lastActive: "5/21/2026" },
];

// ─── Constants ───────────────────────────────────────────────────────────────

const PRIMARY = "#EA580C";
const AVATAR_COLORS = [
  "#F97316","#6366F1","#10B981","#EC4899",
  "#3B82F6","#F59E0B","#8B5CF6","#14B8A6",
];

const STATUS_FILTER_TABS = [
  { key: "all",      label: "All" },
  { key: "active",   label: "Active" },
  { key: "recent",   label: "Recent" },
  { key: "inactive", label: "Inactive" },
  { key: "dormant",  label: "Dormant" },
];

const PER_PAGE = 8;

// ─── Helpers ─────────────────────────────────────────────────────────────────

function initials(name: string) {
  return name.split(" ").map((p) => p[0]).join("").slice(0, 2).toUpperCase();
}

function avatarColor(id: number) {
  return AVATAR_COLORS[id % AVATAR_COLORS.length];
}

function statusDotColor(status: UserStatus) {
  const map: Record<UserStatus, string> = {
    active: "#16A34A",
    pending: "#D97706",
    suspended: "#DC2626",
    dormant: "#94A3B8",
  };
  return map[status];
}

// ─── Sub-components ──────────────────────────────────────────────────────────

const StatusBadge: React.FC<{ status: UserStatus }> = ({ status }) => {
  const styles: Record<UserStatus, React.CSSProperties> = {
    active:    { background: "#DCFCE7", color: "#166534" },
    pending:   { background: "#FEF9C3", color: "#854D0E" },
    suspended: { background: "#FEE2E2", color: "#991B1B" },
    dormant:   { background: "#F1F5F9", color: "#64748B" },
  };
  return (
    <span
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 4,
        padding: "3px 8px",
        borderRadius: 20,
        fontSize: 11,
        fontWeight: 500,
        ...styles[status],
      }}
    >
      <span
        style={{
          width: 5,
          height: 5,
          borderRadius: "50%",
          background: "currentColor",
        }}
      />
      {status.charAt(0).toUpperCase() + status.slice(1)}
    </span>
  );
};

const RolePill: React.FC<{ role: UserRole }> = ({ role }) => {
  const styles: Record<UserRole, React.CSSProperties> = {
    admin:  { background: "#EDE9FE", color: "#5B21B6" },
    driver: { background: "#ECFDF5", color: "#065F46" },
    user:   { background: "#E0F2FE", color: "#075985" },
  };
  return (
    <span
      style={{
        display: "inline-block",
        padding: "2px 8px",
        borderRadius: 4,
        fontSize: 11,
        fontWeight: 500,
        ...styles[role],
      }}
    >
      {role.charAt(0).toUpperCase() + role.slice(1)}
    </span>
  );
};

const UserAvatar: React.FC<{ user: User; size?: number; fontSize?: number }> = ({
  user,
  size = 44,
  fontSize = 14,
}) => {
  if (user.avatarUrl) {
    return (
      <img
        src={user.avatarUrl}
        alt={user.name}
        style={{ width: size, height: size, borderRadius: "50%", objectFit: "cover", flexShrink: 0 }}
      />
    );
  }
  const bg = avatarColor(user.id);
  return (
    <div
      style={{
        width: size,
        height: size,
        borderRadius: "50%",
        background: `${bg}22`,
        color: bg,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontWeight: 600,
        fontSize,
        flexShrink: 0,
      }}
    >
      {initials(user.name)}
    </div>
  );
};

