// ─── Desktop Table ────────────────────────────────────────────────────────────

const DesktopTable: React.FC<{
  users: User[];
  page: number;
  totalFiltered: number;
  onPrev: () => void;
  onNext: () => void;
  onSetPage: (p: number) => void;
}> = ({ users, page, totalFiltered, onPrev, onNext, onSetPage }) => {
  const totalPages = Math.ceil(totalFiltered / PER_PAGE);
  const start = (page - 1) * PER_PAGE + 1;
  const end = Math.min(page * PER_PAGE, totalFiltered);

  return (
    <div
      style={{
        background: "#fff",
        borderRadius: 14,
        border: "1px solid #E2E8F0",
        overflow: "hidden",
      }}
    >
      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
          <thead>
            <tr style={{ background: "#F8FAFC" }}>
              {["", "User", "Role", "Phone", "Joined", "Last Active", "Status", "Actions"].map((h) => (
                <th
                  key={h}
                  style={{
                    padding: "10px 14px",
                    textAlign: "left",
                    fontSize: 11,
                    fontWeight: 600,
                    color: "#64748B",
                    textTransform: "uppercase",
                    letterSpacing: "0.06em",
                    borderBottom: "1px solid #E2E8F0",
                    whiteSpace: "nowrap",
                  }}
                >
                  {h === "" ? <input type="checkbox" /> : h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {users.map((user) => (
              <tr
                key={user.id}
                style={{ borderBottom: "1px solid #F1F5F9", cursor: "pointer" }}
                onMouseEnter={(e) => (e.currentTarget.style.background = "#F8FAFC")}
                onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
              >
                <td style={{ padding: "12px 14px" }}>
                  <input type="checkbox" />
                </td>
                <td style={{ padding: "12px 14px" }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                    <UserAvatar user={user} size={32} fontSize={12} />
                    <div>
                      <div style={{ fontWeight: 500, color: "#0F172A", fontSize: 13 }}>{user.name}</div>
                      <div style={{ fontSize: 11, color: "#64748B" }}>{user.email}</div>
                    </div>
                  </div>
                </td>
                <td style={{ padding: "12px 14px" }}>
                  <RolePill role={user.role} />
                </td>
                <td style={{ padding: "12px 14px", color: "#64748B", fontSize: 12 }}>{user.phone}</td>
                <td style={{ padding: "12px 14px", color: "#64748B", fontSize: 12 }}>{user.joined}</td>
                <td style={{ padding: "12px 14px", color: "#64748B", fontSize: 12 }}>{user.lastActive}</td>
                <td style={{ padding: "12px 14px" }}>
                  <StatusBadge status={user.status} />
                </td>
                <td style={{ padding: "12px 14px" }}>
                  <div style={{ display: "flex", gap: 4 }}>
                    {[
                      { icon: "👁", title: "View" },
                      { icon: "✏️", title: "Edit" },
                      { icon: "🚩", title: "Flag" },
                      { icon: "🗑", title: "Delete" },
                    ].map(({ icon, title }) => (
                      <button
                        key={title}
                        title={title}
                        style={{
                          width: 28,
                          height: 28,
                          border: "1px solid #E2E8F0",
                          borderRadius: 6,
                          background: "transparent",
                          cursor: "pointer",
                          fontSize: 13,
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center",
                        }}
                      >
                        {icon}
                      </button>
                    ))}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "12px 16px",
          borderTop: "1px solid #E2E8F0",
        }}
      >
        <span style={{ fontSize: 12, color: "#64748B" }}>
          Showing {totalFiltered === 0 ? 0 : start}–{end} of {totalFiltered}
        </span>
        <div style={{ display: "flex", gap: 4 }}>
          <button
            onClick={onPrev}
            disabled={page === 1}
            style={{
              width: 30, height: 30, border: "1px solid #E2E8F0",
              borderRadius: 6, background: "transparent", cursor: page === 1 ? "not-allowed" : "pointer",
              fontSize: 14, display: "flex", alignItems: "center", justifyContent: "center",
              opacity: page === 1 ? 0.4 : 1,
            }}
          >
            ‹
          </button>
          {Array.from({ length: totalPages }, (_, i) => i + 1).map((p) => (
            <button
              key={p}
              onClick={() => onSetPage(p)}
              style={{
                width: 30, height: 30,
                border: page === p ? "none" : "1px solid #E2E8F0",
                borderRadius: 6,
                background: page === p ? PRIMARY : "transparent",
                color: page === p ? "#fff" : "#64748B",
                cursor: "pointer",
                fontSize: 12,
                fontWeight: page === p ? 600 : 400,
              }}
            >
              {p}
            </button>
          ))}
          <button
            onClick={onNext}
            disabled={page === totalPages || totalPages === 0}
            style={{
              width: 30, height: 30, border: "1px solid #E2E8F0",
              borderRadius: 6, background: "transparent",
              cursor: page === totalPages ? "not-allowed" : "pointer",
              fontSize: 14, display: "flex", alignItems: "center", justifyContent: "center",
              opacity: page === totalPages || totalPages === 0 ? 0.4 : 1,
            }}
          >
            ›
          </button>
        </div>
      </div>
    </div>
  );
};

// ─── Main Page ────────────────────────────────────────────────────────────────

const UsersPage: React.FC = () => {
  const [search, setSearch] = useState("");
  const [activeTab, setActiveTab] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [roleFilter, setRoleFilter] = useState("all");
  const [page, setPage] = useState(1);

  // Detect mobile
  const [isMobile, setIsMobile] = React.useState(
    () => typeof window !== "undefined" && window.innerWidth < 768
  );
  React.useEffect(() => {
    const mq = window.matchMedia("(max-width: 768px)");
    setIsMobile(mq.matches);
    const handler = (e: MediaQueryListEvent) => setIsMobile(e.matches);
    mq.addEventListener("change", handler);
    return () => mq.removeEventListener("change", handler);
  }, []);

  // Filter logic
  const filtered = useMemo(() => {
    const q = search.toLowerCase();
    return MOCK_USERS.filter((u) => {
      const matchSearch =
        !q ||
        u.name.toLowerCase().includes(q) ||
        u.email.toLowerCase().includes(q) ||
        u.phone.toLowerCase().includes(q);

      const matchTab =
        activeTab === "all" ||
        (activeTab === "active" && u.status === "active") ||
        (activeTab === "inactive" && u.status === "suspended") ||
        (activeTab === "dormant" && u.status === "dormant") ||
        (activeTab === "recent" && u.status === "active"); // approximate

      const matchStatus = statusFilter === "all" || u.status === statusFilter;
      const matchRole = roleFilter === "all" || u.role === roleFilter;

      return matchSearch && matchTab && matchStatus && matchRole;
    });
  }, [search, activeTab, statusFilter, roleFilter]);

  const paginatedUsers = filtered.slice((page - 1) * PER_PAGE, page * PER_PAGE);

  const counts = useMemo(() => ({
    all:      MOCK_USERS.length,
    active:   MOCK_USERS.filter((u) => u.status === "active").length,
    recent:   MOCK_USERS.filter((u) => u.status === "active").length,
    inactive: MOCK_USERS.filter((u) => u.status === "suspended").length,
    dormant:  MOCK_USERS.filter((u) => u.status === "dormant").length,
  }), []);

  const handleTabChange = (key: string) => {
    setActiveTab(key);
    setPage(1);
  };

  const handleSearch = (v: string) => {
    setSearch(v);
    setPage(1);
  };

  // ── MOBILE LAYOUT ──────────────────────────────────────────────────────────
  if (isMobile) {
    return (
      <div style={{ background: "#F9FBFC", minHeight: "100%" }}>

        {/* Page heading + count */}
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 14 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <span style={{ fontSize: 16 }}>👤</span>
            <h1 style={{ fontSize: 18, fontWeight: 700, color: "#0F172A" }}>All Users</h1>
          </div>
          <span
            style={{
              background: "#FFF4EE",
              color: PRIMARY,
              fontSize: 12,
              fontWeight: 600,
              padding: "4px 12px",
              borderRadius: 20,
            }}
          >
            {filtered.length} / {MOCK_USERS.length}
          </span>
        </div>

        {/* Search */}
        <div style={{ position: "relative", marginBottom: 12 }}>
          <span
            style={{
              position: "absolute",
              left: 12,
              top: "50%",
              transform: "translateY(-50%)",
              color: "#94A3B8",
              fontSize: 15,
              pointerEvents: "none",
            }}
          >
            🔍
          </span>
          <input
            type="text"
            placeholder="Search by name, email, or phone…"
            value={search}
            onChange={(e) => handleSearch(e.target.value)}
            style={{
              width: "100%",
              padding: "11px 14px 11px 38px",
              borderRadius: 12,
              border: "1px solid #E2E8F0",
              background: "#fff",
              fontSize: 13,
              color: "#0F172A",
              outline: "none",
              boxSizing: "border-box",
            }}
          />
        </div>

        {/* Filter tabs */}
        <div
          style={{
            display: "flex",
            gap: 6,
            overflowX: "auto",
            paddingBottom: 4,
            marginBottom: 14,
            scrollbarWidth: "none",
            flexWrap: "wrap",
          }}
        >
          {STATUS_FILTER_TABS.map((tab) => {
            const count = counts[tab.key as keyof typeof counts] ?? filtered.length;
            const isActive = activeTab === tab.key;
            return (
              <button
                key={tab.key}
                onClick={() => handleTabChange(tab.key)}
                style={{
                  padding: "7px 14px",
                  borderRadius: 20,
                  border: isActive ? "none" : "1px solid #E2E8F0",
                  background: isActive ? PRIMARY : "#fff",
                  color: isActive ? "#fff" : "#64748B",
                  fontSize: 12,
                  fontWeight: 500,
                  cursor: "pointer",
                  whiteSpace: "nowrap",
                }}
              >
                {tab.label} ({count})
              </button>
            );
          })}
        </div>

        {/* Section label */}
        <div style={{ fontSize: 12, fontWeight: 500, color: "#64748B", marginBottom: 10 }}>
          {STATUS_FILTER_TABS.find((t) => t.key === activeTab)?.label} ({filtered.length})
        </div>

        {/* Cards */}
        {filtered.length === 0 ? (
          <div style={{ textAlign: "center", padding: "40px 0", color: "#94A3B8", fontSize: 14 }}>
            No users found
          </div>
        ) : (
          filtered.map((user) => <MobileUserCard key={user.id} user={user} />)
        )}
      </div>
    );
  }

  // ── DESKTOP LAYOUT ─────────────────────────────────────────────────────────
  return (
    <div>
      {/* Stats row */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(130px, 1fr))",
          gap: 12,
          marginBottom: 20,
        }}
      >
        {[
          { label: "Total Users",  value: MOCK_USERS.length, sub: "↑ 12% this month", subColor: "#16A34A" },
          { label: "Active",       value: counts.active,     sub: "↑ 8% this month",  subColor: "#16A34A" },
          { label: "Pending",      value: MOCK_USERS.filter((u) => u.status === "pending").length, sub: "↑ 3 today", subColor: "#D97706" },
          { label: "Suspended",    value: MOCK_USERS.filter((u) => u.status === "suspended").length, sub: "↓ 5 this week", subColor: "#DC2626" },
        ].map((s) => (
          <div
            key={s.label}
            style={{ background: "#F1F5F9", borderRadius: 12, padding: "14px 16px" }}
          >
            <div style={{ fontSize: 11, color: "#64748B", textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: 4 }}>
              {s.label}
            </div>
            <div style={{ fontSize: 24, fontWeight: 600, color: "#0F172A" }}>{s.value}</div>
            <div style={{ fontSize: 11, color: s.subColor, marginTop: 2 }}>{s.sub}</div>
          </div>
        ))}
      </div>

      {/* Toolbar */}
      <div
        style={{
          background: "#fff",
          borderRadius: 12,
          border: "1px solid #E2E8F0",
          padding: "14px 16px",
          marginBottom: 16,
          display: "flex",
          alignItems: "center",
          gap: 10,
          flexWrap: "wrap",
        }}
      >
        {/* Search */}
        <div style={{ position: "relative", flex: 1, minWidth: 200 }}>
          <span style={{ position: "absolute", left: 10, top: "50%", transform: "translateY(-50%)", color: "#94A3B8", fontSize: 14 }}>
            🔍
          </span>
          <input
            type="text"
            placeholder="Search users…"
            value={search}
            onChange={(e) => handleSearch(e.target.value)}
            style={{
              width: "100%",
              padding: "9px 12px 9px 32px",
              borderRadius: 10,
              border: "1px solid #E2E8F0",
              background: "#F8FAFC",
              fontSize: 13,
              color: "#0F172A",
              outline: "none",
              boxSizing: "border-box",
            }}
          />
        </div>

        {/* Status filter */}
        <select
          value={statusFilter}
          onChange={(e) => { setStatusFilter(e.target.value); setPage(1); }}
          style={{
            padding: "9px 12px",
            borderRadius: 10,
            border: "1px solid #E2E8F0",
            background: "#F8FAFC",
            fontSize: 13,
            color: "#0F172A",
            outline: "none",
            cursor: "pointer",
          }}
        >
          <option value="all">All statuses</option>
          <option value="active">Active</option>
          <option value="pending">Pending</option>
          <option value="suspended">Suspended</option>
          <option value="dormant">Dormant</option>
        </select>

        {/* Role filter */}
        <select
          value={roleFilter}
          onChange={(e) => { setRoleFilter(e.target.value); setPage(1); }}
          style={{
            padding: "9px 12px",
            borderRadius: 10,
            border: "1px solid #E2E8F0",
            background: "#F8FAFC",
            fontSize: 13,
            color: "#0F172A",
            outline: "none",
            cursor: "pointer",
          }}
        >
          <option value="all">All roles</option>
          <option value="admin">Admin</option>
          <option value="driver">Driver</option>
          <option value="user">User</option>
        </select>

        <div style={{ marginLeft: "auto" }}>
          <button
            style={{
              padding: "9px 16px",
              borderRadius: 10,
              border: "none",
              background: PRIMARY,
              color: "#fff",
              fontSize: 13,
              fontWeight: 500,
              cursor: "pointer",
              display: "flex",
              alignItems: "center",
              gap: 6,
            }}
          >
            + Add user
          </button>
        </div>
      </div>

      {/* Table */}
      <DesktopTable
        users={paginatedUsers}
        page={page}
        totalFiltered={filtered.length}
        onPrev={() => setPage((p) => Math.max(1, p - 1))}
        onNext={() => setPage((p) => p + 1)}
        onSetPage={setPage}
      />
    </div>
  );
};

export default UsersPage;
